select
id, user_id, resume_id, section_key, item_index, fragment_text, fragment_hash, create_time, update_time
from resume_fragment


        and id = #{resumeFragment.id}


        and user_id = #{resumeFragment.userId}


        and resume_id = #{resumeFragment.resumeId}


        and section_key = #{resumeFragment.sectionKey}


        and item_index = #{resumeFragment.itemIndex}


        and fragment_text = #{resumeFragment.fragmentText}


        and fragment_hash = #{resumeFragment.fragmentHash}


        and create_time = #{resumeFragment.createTime}


        and update_time = #{resumeFragment.updateTime}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from resume_fragment


        and id = #{id}


        and user_id = #{userId}


        and resume_id = #{resumeId}


        and section_key = #{sectionKey}


        and item_index = #{itemIndex}


        and fragment_text = #{fragmentText}


        and fragment_hash = #{fragmentHash}


        and create_time = #{createTime}


        and update_time = #{updateTime}
